<section class="page-hero"><div class="mx-auto max-w-content px-5 py-20 lg:px-6 lg:py-28"><p class="eyebrow">Education and stories</p><h1 class="page-title mt-5">The Emb Chronicles blog</h1><p class="mt-6 max-w-2xl text-lg leading-8 text-muted">Clear fertility education, treatment insights, community perspectives, and guidance for the journey ahead.</p></div></section>
<section class="section"><div class="mx-auto max-w-content px-5 lg:px-6"><?php if ($posts): ?><div class="grid gap-6 md:grid-cols-2 lg:grid-cols-3"><?php foreach ($posts as $post): ?><article class="event-card flex flex-col"><?php if ($post['cover_image']): ?><a href="<?= e(url('/blog/' . $post['slug'])) ?>"><img src="<?= e(media_url($post['cover_image'])) ?>" alt="<?= e($post['cover_alt']) ?>" class="aspect-[4/3] w-full object-cover" loading="lazy"></a><?php endif; ?><div class="flex flex-1 flex-col p-6"><div class="flex items-center gap-2"><span class="chip"><?= e(format_date($post['published_at'])) ?></span><?php if ($post['is_featured']): ?><span class="chip chip-featured">Featured</span><?php endif; ?></div><h2 class="mt-5 font-display text-3xl text-wine"><a href="<?= e(url('/blog/' . $post['slug'])) ?>"><?= e($post['title']) ?></a></h2><p class="mt-3 text-sm leading-6 text-muted"><?= e($post['excerpt']) ?></p><a class="text-link mt-auto pt-6" href="<?= e(url('/blog/' . $post['slug'])) ?>">Read article →</a></div></article><?php endforeach; ?></div><?php else: ?><div class="empty-state"><h2 class="font-display text-3xl text-wine">Articles are coming soon</h2><p class="mt-3">Please check back for new fertility education and community stories.</p></div><?php endif; ?></div></section>
